//! Deterministic CPU display-list rasterizer (RGBA, no platform font dependency).
use crate::layout::{LayoutBox,Rect};
#[derive(Clone,Debug,PartialEq)] pub enum Op { Fill(Rect,[u8;4]), Text(f32,f32,String,[u8;4]), Clip(Rect), Image(Rect,Vec<u8>) }
#[derive(Clone,Debug)] pub struct Canvas { pub width:u32,pub height:u32,pub pixels:Vec<u8>,pub ops:Vec<Op> }
impl Canvas { pub fn new(w:u32,h:u32)->Self{Self{width:w,height:h,pixels:vec![0;w as usize*h as usize*4],ops:vec![]}} pub fn display_list(&mut self,b:&LayoutBox){self.ops.push(Op::Fill(b.rect,b.background));for c in &b.children{self.display_list(c)}if let Some(t)=&b.text{self.ops.push(Op::Text(b.content.x,b.content.y,t.clone(),[0,0,0,255]))}} pub fn rasterize(&mut self){for op in self.ops.clone(){if let Op::Fill(r,c)=op{let x0=r.x.max(0.) as u32;let y0=r.y.max(0.) as u32;let x1=r.right().min(self.width as f32) as u32;let y1=r.bottom().min(self.height as f32) as u32;for y in y0..y1{for x in x0..x1{let i=((y*self.width+x)*4)as usize;let a=c[3] as u32;for k in 0..3{self.pixels[i+k]=((c[k]as u32*a+self.pixels[i+k]as u32*(255-a))/255)as u8;}self.pixels[i+3]=255;}}}}} pub fn rgba(&self)->&[u8]{&self.pixels} }
#[cfg(test)] mod tests {use super::*;#[test]fn selected_pixel(){let b=LayoutBox{rect:Rect{x:0.,y:0.,width:2.,height:2.},content:Rect::default(),children:vec![],text:None,background:[255,0,0,255]};let mut c=Canvas::new(3,3);c.display_list(&b);c.rasterize();assert_eq!(&c.pixels[..4],[255,0,0,255]);}}
